import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.ClientStartItemCooldown{Category: "minecraft:shield", Duration: 300}
SHIELD = bytes.fromhex("106d696e6563726166743a736869656c64d804")

# generated by gophertunnel b8bd735:
# &packet.ClientStartItemCooldown{Category: "", Duration: -1}
NEGATIVE = bytes.fromhex("0001")

GOLDENS = [
    pytest.param(
        version.PlayerStartItemCooldownPacket(item_category="minecraft:shield", duration_ticks=300),
        SHIELD,
        id=f"{name}-shield",
    )
    for name, version in VERSIONS.items()
] + [
    pytest.param(
        version.PlayerStartItemCooldownPacket(item_category="", duration_ticks=-1),
        NEGATIVE,
        id=f"{name}-negative-duration",
    )
    for name, version in VERSIONS.items()
]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_player_start_item_cooldown_is_packet_176(version):
    assert version.PACKETS[176] is version.PlayerStartItemCooldownPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_start_item_cooldown_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_start_item_cooldown_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_a_category_over_127_bytes_takes_a_two_byte_length_prefix(version):
    packet = version.PlayerStartItemCooldownPacket(item_category="a" * 200, duration_ticks=1)
    wire = bytes(packet)
    assert len(wire) == 203
    assert version.PlayerStartItemCooldownPacket.from_bytes(wire) == packet
